import { describe, expect, it } from "vitest";
import { SYNTHETIC_CLINICAL_RELEASE } from "./synthetic-content";
import {QUESTION_STATS1_ACCEPTED_SOURCE_RELEASE} from "./question-stats1-accepted-20261108";
import {QUESTION_PROGRAM_BATCH3_ACCEPTED_SOURCE_VIEWS} from "./question-program-batch3-accepted-20261111";
import type {SyntheticClinicalCase} from "./schema";

// The owner-approved non-clinical statistics style retains exact reviewed
// presentation-only staff profiles. They never introduce patient demographics.
// Every other staff discussion keeps the original no-profile assertion.
function expectStaffProfiles(clinicalCase:SyntheticClinicalCase):void {
 const exact=[...QUESTION_STATS1_ACCEPTED_SOURCE_RELEASE.cases,...QUESTION_PROGRAM_BATCH3_ACCEPTED_SOURCE_VIEWS["topic-batch3-statistics"]!.cases].find(c=>c.id===clinicalCase.id&&
  c.participant?.kind==="employee_discussion"&&c.decisionNodes[0]!.questionVariantId===clinicalCase.decisionNodes[0]!.questionVariantId);
 if(!exact){expect(clinicalCase.approvedInstantiationProfiles,clinicalCase.id).toBeUndefined();return;}
 expect(clinicalCase.approvedInstantiationProfiles,clinicalCase.id).toEqual(exact.approvedInstantiationProfiles);
 expect(clinicalCase.approvedInstantiationProfiles).toHaveLength(1);
 for(const profile of clinicalCase.approvedInstantiationProfiles!){
  expect(profile.prototypeDemographics).toBeUndefined();expect(profile.prototypeVitalSigns).toBeUndefined();
  expect(profile.presentation).toBe(clinicalCase.presentation);expect(profile.chiefComplaint).toBe(exact.chiefComplaint);
  expect(Object.keys(profile).sort()).toEqual(["chiefComplaint","id","presentation"]);
 }
}

const MULTI_PATIENT_FRAMING = [
  /\bwhich patient\b/i,
  /\b(?:four|several|multiple) (?:stable )?(?:adults|patients)\b/i,
  /\b(?:reviewing|counseling) patients\b/i,
  /\bwhich (?:presentation|referral profile)\b/i,
];

const PATIENT_REFERENCE =
  /(?:\{patientName\}|\b(?:patient|adult|woman|man|recipient|they|she|he|\d{1,3}-year-old)\b)/i;
const STORY_CUE =
  /\b(?:asks?|wants?|requests?|reports?|returns?|arrives?|attends?|noticed|notes?|describes?|is seen|is reviewed|is offered|is invited|comes?|visits?|brings?|discuss(?:es|ing)?|reviews?|reviewing|hoping|considering|counseled|diagnosed|hypercalcemia|shows?|showing|discovered|identifies|referred|confirming|evaluated|evaluates?|assess(?:ed|ing)|wakes?|found|undergoing|preparing|prepared|presents?|has|have|had|develops?|confirms|completed|scheduled|plans|starts|persists|decides|receives|reads?|sees?|declines?|lacks?|overhears?|recognizes?|waits?|considers?|compares?|moves?|records?|measures?|tabulates?|cross-classifies|designs?|tests?|recalls?|cannot|eats?|viene|consulta|llega|quiere|dice|pregunta|está|comprende)\b/i;
const ALTERNATE_PATIENT_CHOICE =
  /^(?:a|an|fit) (?:patient|adult|woman|man)\b/i;

function normalized(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

describe("playable one-patient narratives", () => {
  it("anchors every admitted case to one patient with a brief story", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.id.startsWith("case.l2.")) continue;
      if (clinicalCase.participant?.kind === "employee_discussion") {
        expect(clinicalCase.presentation, clinicalCase.id).toContain(
          "{patientName}",
        );
        expect(clinicalCase.presentation, clinicalCase.id).toMatch(STORY_CUE);
        expect(clinicalCase.prototypeDemographics, clinicalCase.id).toBeUndefined();
        expect(clinicalCase.prototypeVitalSigns, clinicalCase.id).toBeUndefined();
        expectStaffProfiles(clinicalCase);
        continue;
      }
      expect(clinicalCase.presentation, clinicalCase.id).toMatch(
        PATIENT_REFERENCE,
      );
      expect(clinicalCase.presentation, clinicalCase.id).toMatch(STORY_CUE);
      for (const pattern of MULTI_PATIENT_FRAMING) {
        expect(clinicalCase.presentation, clinicalCase.id).not.toMatch(
          pattern,
        );
      }
    }
  });

  it("keeps decision prompts tied to that encounter instead of restating the chart", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.id.startsWith("case.l2.")) continue;
      const firstPresentationSentence =
        clinicalCase.presentation.match(/^.*?[.!?](?:\s|$)/)?.[0] ?? "";
      for (const node of clinicalCase.decisionNodes) {
        for (const pattern of MULTI_PATIENT_FRAMING) {
          expect(node.stem, node.id).not.toMatch(pattern);
        }
        if (firstPresentationSentence.length >= 50) {
          expect(normalized(node.stem), node.id).not.toContain(
            normalized(firstPresentationSentence),
          );
        }
      }
    }
  });

  it("uses alternative findings rather than a lineup of different patients", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      for (const node of clinicalCase.decisionNodes) {
        for (const choice of node.answerChoices) {
          expect(choice.label, `${node.id}:${choice.id}`).not.toMatch(
            ALTERNATE_PATIENT_CHOICE,
          );
        }
      }
    }
  });

  it("keeps explicitly female stories attached to female chart identities", () => {
    for (const clinicalCase of SYNTHETIC_CLINICAL_RELEASE.cases) {
      if (clinicalCase.participant?.kind === "employee_discussion") {
        expect(clinicalCase.prototypeDemographics, clinicalCase.id).toBeUndefined();
        expectStaffProfiles(clinicalCase);
        continue;
      }
      const profiles = clinicalCase.approvedInstantiationProfiles ?? [];
      if (profiles.length > 0) {
        for (const profile of profiles) {
          if (/\b(?:woman|she|her)\b/i.test(profile.presentation)) {
            expect(profile.prototypeDemographics?.sexLabel, `${clinicalCase.id}/${profile.id}`).toBe("Female");
          }
        }
      } else if (/\b(?:woman|she|her)\b/i.test(clinicalCase.presentation)) {
        expect(clinicalCase.prototypeDemographics?.sexLabel, clinicalCase.id).toBe("Female");
      }
    }
  });
});

import { readFileSync } from "node:fs";
// Entirely synthetic. Uses shipped geometry/content and fresh initializer data;
// never reads an owner export or the private profiling backup.
import {
  createInitialGameState, deserializeGameState, gameReducer, getDefaultDoorOffset, getNewPeriopServiceOperationPhases,
  getCurrentCapabilities, hasOutstandingDiagnosticWork, getRoomDefinition, getRoomNavigationAnchor, getStaffRoleDefinition, planDiagnosticOrder,
  PROTOTYPE_DOMAIN_CONTEXT, validateDoorPlacement,
  type DoorState, type EmployeeState, type EncounterState, type GameState, type ServiceOperationState,
} from "@gamify-surgery/game-domain";
import { getServiceIncomeLine } from "@gamify-surgery/balance-config";
import {QUESTION_PROGRAM_BATCH3_RETAINED_CASES,QUESTION_SHIP_MANIFEST} from "@gamify-surgery/clinical-content";

export function createDiagnosticWorkload(): { state: GameState; chartId: string } {
  let state = createInitialGameState(PROTOTYPE_DOMAIN_CONTEXT, {
    campaignId: "campaign.synthetic.diagnostic-workload", campaignSeed: "diagnostic-workload", createdAtRealMs: 0,
  });
  const template = Object.values(state.encounters)[0]!;
  state.facilityLevel = 3; state.facilityTick = 6760; state.paused = false;
  state.cash = 100_000; state.cashCents = 10_000_000;
  state.serviceAppointmentsEnabled = false; state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  state.nextEmployeeDiscussionTick = Number.MAX_SAFE_INTEGER;
  const front = { ...state.rooms[0]!, id: "room.instance.founder_desk", roomDefinitionId: "room.front_desk", x: 3, y: 28, orientation: 0 as const, doorSide: null };
  state.rooms = [front]; state.doors = [{ id: "synthetic.exterior", roomId: front.id, side: "south", offset: 2, exterior: true }];
  for (let x = 3; x <= 68; x++) state.rooms.push({ id: `synthetic.hall.${x}`, roomDefinitionId: "room.hallway", x, y: 26, orientation: 0, doorSide: null, upgradeLevel: 1 });
  for (let y = 21; y < 26; y++) state.rooms.push({ id: `synthetic.spine.${y}`, roomDefinitionId: "room.hallway", x: 68, y, orientation: 0, doorSide: null, upgradeLevel: 1 });
  for (let x = 3; x < 8; x++) state.rooms.push({ id: `synthetic.entry.${x}`, roomDefinitionId: "room.hallway", x, y: 27, orientation: 0, doorSide: null, upgradeLevel: 1 });
  const definitions = ["examination", "waiting", "bathroom", "phlebotomy", "xray", "endoscopy", "periop_recovery", "ambulatory_or", "laboratory", "reading", "training", "staff_break", "evs_closet", "maintenance_workshop", "imaging_control", "ultrasound", "ct", "glp1_telehealth_suite", "pharmacy"];
  let x = 3;
  for (const name of definitions) {
    const definition = getRoomDefinition(`room.${name}`)!;
    state.rooms.push({ id: `synthetic.room.${name}`, roomDefinitionId: definition.id, x, y: 26 - definition.height, orientation: 0, doorSide: null, upgradeLevel: 1, cleanliness: 100 });
    x += definition.width;
  }
  const facility = PROTOTYPE_DOMAIN_CONTEXT.balanceRelease.facility;
  const addDoor = (door: DoorState) => {
    if (!validateDoorPlacement(door, state.rooms, state.doors, getRoomDefinition, facility.gridWidth, facility.gridHeight, new Set(facility.protectedRoomDefinitionIds)).valid) return false;
    state.doors.push(door); return true;
  };
  for (const room of state.rooms.filter(room => room.roomDefinitionId !== "room.hallway")) {
    const definition = getRoomDefinition(room.roomDefinitionId)!;
    const side = room === front ? "north" : "south";
    let added = false;
    for (const offset of [getDefaultDoorOffset(room, definition, side), ...Array.from({ length: definition.width }, (_, i) => i)]) {
      if (addDoor({ id: `synthetic.door.${state.doors.length}`, roomId: room.id, side, offset, exterior: false })) { added = true; break; }
    }
    if (!added) throw new Error(`Synthetic room has no valid circulation door: ${room.roomDefinitionId}`);
  }
  outer: for (const room of state.rooms) for (const side of ["north", "east", "south", "west"] as const) for (let offset = 0; offset < 6; offset++) {
    if (state.doors.length === 41) break outer;
    addDoor({ id: `synthetic.door.${state.doors.length}`, roomId: room.id, side, offset, exterior: false });
  }
  if (state.doors.length !== 41) throw new Error("Synthetic workload requires 41 legal doors");
  // Aggregate role mix from the profiling report's approved read-only probe;
  // all employee records below are freshly generated synthetic records.
  const staff = [["receptionist", 1, "front_desk"], ["imaging_technician", 2, "xray"], ["phlebotomist", 1, "phlebotomy"],
    ["periop_nurse", 2, "periop_recovery"], ["endoscopist", 2, "endoscopy"], ["endoscopy_nurse", 2, "endoscopy"],
    ["glp1_np", 6, "glp1_telehealth_suite"], ["evs_worker", 1, "evs_closet"], ["pharmacist", 1, "pharmacy"],
    ["or_nurse", 1, "ambulatory_or"], ["surgeon", 1, "ambulatory_or"], ["radiologist", 4, "reading"],
    ["repair_person", 1, "maintenance_workshop"]] as const;
  state.employees = [];
  for (const [role, count, home] of staff) for (let i = 0; i < count; i++) {
    const definitionId = `staff.${role}`, roleDefinition = getStaffRoleDefinition(definitionId);
    if (!roleDefinition) throw new Error(`Unknown synthetic staff role ${definitionId}`);
    const room = home === "front_desk" ? front : state.rooms.find(room => room.id === `synthetic.room.${home}`)!;
    const location = getRoomNavigationAnchor(room, getRoomDefinition(room.roomDefinitionId)!, "staff");
    state.employees.push({ id: `synthetic.employee.${state.employees.length}`, staffRoleDefinitionId: definitionId, displayName: `Synthetic employee ${state.employees.length}`,
      appearance: state.founder.appearance, hiredAtFacilityTick: 0, salaryPerExpenseInterval: 26, morale: 80, trainingLevel: 1,
      homeRoomInstanceId: room.id, location, path: [location], pathIndex: 0, lastMovedAtFacilityTick: 0, lastPraisedAtFacilityTick: null,
      nextIdleActionAtFacilityTick: Number.MAX_SAFE_INTEGER, facilityTask: null } satisfies EmployeeState);
  }
  const anchor = getRoomNavigationAnchor(front, getRoomDefinition(front.roomDefinitionId)!);
  state.environment.founderLocation = anchor; state.environment.founderActivity = null; state.environment.pendingFounderConsult = null;
  state.encounters = {};
  // This fixture constructs already frozen historical diagnostic encounters.
  // A later fresh-case replacement must not substitute their original nodes.
  const legacyId="case.esophageal-dysphagia.bread-sticking";
  const clinicalCase = PROTOTYPE_DOMAIN_CONTEXT.clinicalRelease.cases.find(entry => entry.id === legacyId) ??
    QUESTION_PROGRAM_BATCH3_RETAINED_CASES.find(entry=>entry.id===legacyId)!;
  if(!clinicalCase || (!PROTOTYPE_DOMAIN_CONTEXT.clinicalRelease.cases.some(entry=>entry.id===legacyId) &&
    !QUESTION_SHIP_MANIFEST.replacements.some(row=>row.replaces===legacyId) &&
    !QUESTION_SHIP_MANIFEST.topicConsolidations.some(row=>row.replaces.includes(legacyId))))throw new Error("Unbound retained diagnostic fixture");
  for (let i = 0; i < 3; i++) {
    const encounter: EncounterState = { ...structuredClone(template), id: `synthetic.encounter.${i}`, patientDisplayName: `Synthetic patient ${i}`,
      frozenCase: structuredClone(clinicalCase), arrivalClass: "routine", lifecycle: "active_action_required", checkInStatus: "checked_in",
      patientLocation: anchor, patientMovement: null, assignedRoomInstanceId: null, pendingResult: null, currentNodeIndex: 0,
      steps: clinicalCase.decisionNodes.map((node, nodeIndex) => ({ nodeIndex, decisionNodeId: node.id, questionVariantId: node.questionVariantId,
        primaryConceptId: node.primaryConceptId, status: nodeIndex ? "locked" : "action_required", answer: null, result: null })) };
    state.encounters[encounter.id] = encounter;
  }

  state.serviceOperations = [];
  for (let i = 0; i < 9; i++) {
    const line = ["income.ambulatory_operation", "income.endoscopy", "income.endoscopy", "income.endoscopy", "income.endoscopy", "income.advanced_endoscopy", "income.xray", "income.ultrasound", "income.collection"][i]!;
    const phases = getNewPeriopServiceOperationPhases(line) ?? getServiceIncomeLine(line)!.operation!.phases;
    state.serviceOperations.push({ id: `synthetic.service.${i}`, incomeLineId: line, catalogVersion: 1, actorKind: "visitor", actorId: `synthetic.visitor.${i}`,
      displayName: `Synthetic queued service ${i}`, appearance: state.founder.appearance, status: "waiting_for_resources", createdAtFacilityTick: state.facilityTick,
      waitDeadlineFacilityTick: state.facilityTick + 600, startedAtFacilityTick: null, completedAtFacilityTick: null, cancelledAtFacilityTick: null,
      quoteFee: 80, phaseIndex: 0, phaseStartedAtFacilityTick: null, phaseEndsAtFacilityTick: null, reservedRoomInstanceIds: [], reservedEmployeeIds: [], providerReservation: null,
      location: anchor, path: [], pathIndex: 0, lastMovedAtFacilityTick: state.facilityTick, cancellationReason: null,
      frozenOperationPhases: JSON.parse(JSON.stringify(phases)) as ServiceOperationState["frozenOperationPhases"] } satisfies ServiceOperationState);
  }
  // Construct an already operating clinic using the real reducer, rather than
  // timing an artificial simultaneous start of nine independent service chains.
  // Keep queued work alongside dispatched/walking phases, as in the report.
  for (let i = 0; i < 12; i++) state = gameReducer(state, { type: "ADVANCE_TICK", operationId: `synthetic.setup.${i}`, advancedAtRealMs: 1800000000000 + i * 1000 });
  for (let i = 0; i < 2; i++) {
    const encounter = state.encounters[`synthetic.encounter.${i}`]!;
      const quote = planDiagnosticOrder(state, { orderId: `synthetic.order.${i}`, encounterId: encounter.id, serviceId: i ? "service.colonoscopy" : "service.endoscopy", resultKind: "visual" });
      if (quote.kind !== "planned") throw new Error(`Synthetic outstanding diagnostic order unavailable: ${quote.reason}; capabilities ${[...getCurrentCapabilities(state)].join(",")}`);
      encounter.lifecycle = "active_pending_result";
      encounter.pendingResult = { operationId: `synthetic.pending.${i}`, gateId: "synthetic.gate", originatingNodeIndex: 0,
        resultTypeId: "service.endoscopy", pendingLabel: "Synthetic queued work", resultNarrative: "Synthetic fixture result", routeId: "synthetic.route", routeDisplayName: "Synthetic onsite work",
        scheduledAtTick: state.facilityTick, serviceDurationTicks: 60, durationTicks: 60, dueTick: state.facilityTick + 60,
        deliveredAtTick: null, offsiteReturnStartedAtTick: null, offsiteTravel: null, patientTravel: null, diagnosticTiming: quote.plan };
  }
  // Public retained QA history supplies authentic FSRS/audit payload at account
  // save scale. No private state, copied owner names, invented reviews or byte
  // padding. Keep current operational geometry/actors/orders independent.
  const retained = JSON.parse(readFileSync(new URL("./level-five-integration-checkpoints-20261012.json", import.meta.url), "utf8"))["integration-lower-repeat"];
  const history = deserializeGameState(JSON.stringify(retained));
  const clockOffset = history.facilityTick - state.facilityTick;
  const historyClock = <T,>(value: T, key = ""): T => {
    if (typeof value === "number" && (key === "facilityTick" || key === "dueTick" || key.endsWith("AtTick") || key.endsWith("FacilityTick"))) return Math.max(0, value - clockOffset) as T;
    if (value === null || typeof value !== "object" || key === "frozenCase") return value;
    if (Array.isArray(value)) return value.map(entry => historyClock(entry)) as T;
    return Object.fromEntries(Object.entries(value).map(([field, entry]) => [field, historyClock(entry, field)])) as T;
  };
  const filed = Object.fromEntries(Object.entries(history.encounters).filter(([, encounter]) =>
    (encounter.lifecycle === "resolved" || encounter.lifecycle === "resolved_summary_available") &&
    encounter.patientLocation === null && encounter.patientMovement === null &&
    (!encounter.pendingResult?.diagnosticTiming || !hasOutstandingDiagnosticWork(encounter.pendingResult.diagnosticTiming))));
  state.encounters = { ...historyClock(filed), ...state.encounters };
  state.serviceOperations.push(...historyClock(history.serviceOperations.filter(operation => (operation.status === "completed" || operation.status === "cancelled") && operation.clinicVisit?.pediatricFamilyId === undefined)));
  state.learningHistories = { ...state.learningHistories, ...historyClock(history.learningHistories) };
  state.schedulerPins = history.schedulerPins;
  state.reviewIntents = historyClock(history.reviewIntents);
  state.settlements = historyClock(history.settlements);
  state.serviceIncomeReceipts = historyClock(history.serviceIncomeReceipts);
  state.events = historyClock(history.events);
  for (const [key, value] of Object.entries(history)) if (key.endsWith("Sequence") && typeof value === "number") {
    (state as unknown as Record<string, unknown>)[key] = Math.max(value, Number((state as unknown as Record<string, unknown>)[key] ?? 0));
  }
  state.openChartEncounterId = "synthetic.encounter.2"; state.attendedEncounterId = null;
  // Setup-only canonicalization, using the ordinary legacy/public fixture adapter.
  return { state: deserializeGameState(JSON.stringify(state)), chartId: state.openChartEncounterId };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { lintQuestion } from "./lint.mjs";
import { inventoryRelease, preAnswerFields, collectAuthoredMetadata, authoredRationales } from "./bank.mjs";
const choices=labels=>labels.map((label,i)=>({id:"choice"+i,label,isCorrect:i===0}));
const lint=(labels,fields={},concept={})=>lintQuestion({variantId:"question.test.r2",caseId:"case.test",choices:choices(labels),fields,concept});
const has=(r,rule)=>r.findings.some(f=>f.rule===rule);

test("reports key-only phrases and exact reconstructable spans",()=>{
  const fields={presentation:"The chart repeats plasma free metanephrines here.",stem:"Which study?"};
  const cs=choices(["Plasma free metanephrines","Dexamethasone suppression test","Aldosterone renin ratio"]);
  const r=lintQuestion({variantId:"q",caseId:"c",fields,choices:cs});
  assert(has(r,"key-only-phrase-overlap"));
  for(const f of r.findings)for(const e of f.evidence){const original=e.choiceId?cs.find(c=>c.id===e.choiceId).label:fields[e.field];assert.equal(original.slice(e.start,e.end),e.text);}
  assert(!has(lint(["Plasma assay","Urine assay","Saliva assay"],{stem:"Which assay?"}),"key-only-word-overlap"));
});

test("owner rule flags X alone in either key or distractor, with exact spans",()=>{
  const r=lint(["Compression stockings alone","Endovenous ablation","Foam sclerotherapy"]);
  const f=r.findings.find(f=>f.rule==="option-alone");assert(f);assert.equal(f.evidence[0].text,"alone");
  assert.equal(f.evidence[0].choiceId,"choice0");
  assert(has(lint(["Hospital assessment","Diet advice alone","Repeat potassium"]),"option-alone"));
  assert(!has(lint(["Compression stockings","Endovenous ablation","Foam sclerotherapy"]),"option-alone"));
});

test("owner rule compares generic individualization with concrete options",()=>{
  for(const term of ["Individualized vascular consultation","Tailored management","Shared-decision planning","Shared decision making"])
    assert(has(lint([term,"Endovenous ablation","Compression stockings"]),"option-generic-individualization"),term);
  assert(!has(lint(["Tailored management","Individualized management","Shared planning"]),"option-generic-individualization"));
  assert(!has(lint(["Individualized endovenous ablation","Foam sclerotherapy","Compression stockings"]),"option-generic-individualization"));
});

test("owner rule asks for a named treatment while retaining exact candidate spans",()=>{
  const r=lint(["Esophageal treatment assessment","Laparoscopic Heller myotomy","Oral omeprazole therapy"]);
  const f=r.findings.find(f=>f.rule==="unnamed-treatment-action");assert(f);
  assert.equal(f.evidence[0].text,"treatment assessment");assert.equal(f.evidence[0].choiceId,"choice0");
  for(const label of ["Management discussion","Treatment planning"])assert(has(lint([label,"Myotomy","Omeprazole"]),"unnamed-treatment-action"));
  assert(!has(lint(["Repeat diagnostic manometry","Laparoscopic Heller myotomy","Oral omeprazole therapy"]),"unnamed-treatment-action"));
});

test("image inventory checks visible descriptions and captions, excluding the asset path",()=>{
  const cs={presentation:"{patientName} has dysphagia.",decisionNodes:[{stem:"Which interpretation?",exhibit:{kind:"image",caption:"Pressure tracing",assetPath:"clinical-exhibits/achalasia-key.png",description:"The junction relaxes slowly."}}]};
  const fields=preAnswerFields(cs,0);
  assert.equal(fields["exhibit.caption"],"Pressure tracing");assert.equal(fields["exhibit.description"],"The junction relaxes slowly.");
  assert(!Object.hasOwn(fields,"exhibit.assetPath"));assert(!Object.values(fields).some(v=>String(v).includes("achalasia-key")));
  assert(has(lint(["Slow junction relaxation","Absent body contraction","Normal propagation"],fields),"key-only-word-overlap"));
});

test("investigation categories recognize full modality names and physiological/pathological studies",()=>{
  const task={stem:"Which investigation should be arranged?"};
  assert(!has(lint(["Repeat high-resolution manometry","Obtain a timed barium esophagram","Obtain pH-impedance monitoring"],task),"heterogeneous-option-category"));
  assert(!has(lint(["Obtain ultrasonography","Obtain magnetic resonance imaging","Obtain computed tomography"],task),"heterogeneous-option-category"));
  assert(!has(lint(["Perform an excisional biopsy","Perform a punch biopsy","Request deeper histological sections"],task),"heterogeneous-option-category"));
  assert(has(lint(["Obtain ultrasound","Obtain computed tomography","Achalasia"],task),"heterogeneous-option-category"));
});

test("owner availability cues are found in presentation, task, update and exhibit without using feedback metadata",()=>{
  for(const phrase of ["The patient is available for immediate transfer.","HIDA is available and won't delay care.","She can swallow and medicines are available."]){
    for(const field of ["presentation","stem","currentUpdate","exhibit.caption"]){
      const r=lint(["Hospital assessment","Repeat potassium","Diet advice"],{[field]:phrase});
      const findings=r.findings.filter(f=>f.rule==="availability-permission-cue");assert(findings.length,phrase);
      for(const f of findings){const e=f.evidence[0];assert.equal(e.field,field);assert.equal(phrase.slice(e.start,e.end),e.text);}
    }
  }
  assert(!has(lint(["Alpha plan","Beta plan","Gamma plan"],{presentation:"She brings the completed ultrasound report."}),"availability-permission-cue"));
});

test("owner findings rule flags supplied eligibility and named rejection but permits a supplied diagnosis for management",()=>{
  for(const phrase of ["The nodule meets biopsy criteria.","Suspicious features meeting biopsy criteria.","The ultrasound is inconclusive."])
    assert(has(lint(["Thyroid FNA","Thyroid scan","Repeat ultrasound"],{presentation:phrase}),"supplied-clinical-conclusion"),phrase);
  const presentation="The team diagnosed hyperacute antibody-mediated rejection.";
  assert(has(lint(["Preformed antibodies","New antibodies","Activated T cells"],{presentation,stem:"Which immune effector explains this?"}),"supplied-clinical-conclusion"));
  assert(!has(lint(["Plan A","Plan B","Plan C"],{presentation,stem:"Which management plan is appropriate?"}),"supplied-clinical-conclusion"));
  assert(!has(lint(["Thyroid FNA","Thyroid scan","Repeat ultrasound"],{presentation:"Ultrasound shows a solid hypoechoic nodule with irregular margins."}),"supplied-clinical-conclusion"));
});

test("owner clarity rules distinguish bare negative imaging and unqualified cervical from actual findings and explicit sites",()=>{
  for(const presentation of ["Mammography and ultrasound are negative.","She has negative imaging."])
    assert(has(lint(["Biopsy referral","Breast MRI","Repeat ultrasound"],{presentation}),"unexplained-negative-imaging"));
  assert(!has(lint(["Biopsy referral","Breast MRI","Repeat ultrasound"],{presentation:"At the palpable site, ultrasound shows no solid or cystic correlate."}),"unexplained-negative-imaging"));
